package cn.sifangguan.hotelaios.finance;
import cn.sifangguan.hotelaios.shared.security.AccessPolicy;
import org.springframework.jdbc.core.namedparam.*;
import org.springframework.stereotype.Component;
import java.util.*;
import static cn.sifangguan.hotelaios.finance.FinanceV2Support.*;

/** Trusted source adapter: no client-supplied snapshots, SQL names, object keys or inferred lineage. */
@Component
public class FinanceArchiveSources {
 private FinanceArchiveExtendedSources extended;
 @org.springframework.beans.factory.annotation.Autowired public void setExtended(FinanceArchiveExtendedSources extended){this.extended=extended;}
 private final NamedParameterJdbcTemplate jdbc;private final AccessPolicy access;private final FinanceService claims;private final FinanceOperationsService operations;private final FinanceAccountingService accounting;private final FinanceBusinessService business;private final FinanceInsightService insights;private final FinanceMigrationService migration;
 public FinanceArchiveSources(NamedParameterJdbcTemplate jdbc,AccessPolicy access,FinanceService claims,FinanceOperationsService operations,FinanceAccountingService accounting,FinanceBusinessService business,FinanceInsightService insights,FinanceMigrationService migration){this.jdbc=jdbc;this.access=access;this.claims=claims;this.operations=operations;this.accounting=accounting;this.business=business;this.insights=insights;this.migration=migration;}
 public static final List<String> TYPES=List.of("CLAIM","OPERATION","REVENUE","PAYROLL","INTERCOMPANY","VOUCHER","INSIGHT","TAX_RETURN","MIGRATION","SUPPLY_RECOGNITION","ASSET_CARD","ACCRUAL","ASSET_GAIN","BOOK_REPORT");
 public Map<String,Object> resolve(String type,UUID source){if(!TYPES.contains(type))throw bad("财务档案来源类型无效");if(FinanceArchiveExtendedSources.TYPES.contains(type)){if(extended==null)throw bad("专项档案来源尚未接入");return extended.resolve(type,source);}var p=access.principal();var b=base(p).addValue("id",source);Map<String,Object> detail=new LinkedHashMap<>(sourceDetail(type,source));
  var cashMovements=new ArrayList<Map<String,Object>>();if(type.equals("REVENUE")){cashMovements.addAll(jdbc.queryForList("select m.* from fb_revenue_movement m join fb_revenue_entry e on e.tenant_id=m.tenant_id and e.id=m.entry_id join fb_revenue_batch old on old.tenant_id=e.tenant_id and old.id=e.batch_id join fb_revenue_batch q on q.tenant_id=old.tenant_id and q.id=:id where m.tenant_id=:tenant and e.hotel_id=q.hotel_id and e.company_id=q.company_id and old.source=q.source and old.channel=q.channel and old.business_date=q.business_date order by m.occurred_on,m.id",b));detail.put("cashMovements",value(cashMovements));}
  var hotels=new LinkedHashSet<UUID>();var companies=new LinkedHashSet<UUID>();if(type.equals("INSIGHT")){var frozen=map(detail.get("snapshot"));for(Object h:(List<?>)frozen.get("scope"))hotels.add(id(h));for(var report:rows(frozen.get("books")))companies.add(id(report.get("companyId")));}else if(Set.of("VOUCHER","MIGRATION").contains(type)){var book=jdbc.queryForMap("select hotel_id,company_id from fa_book where tenant_id=:tenant and id=:id",base(p).addValue("id",id(detail.get("bookId"))));hotels.add(id(book.get("hotel_id")));companies.add(id(book.get("company_id")));}else{hotels.add(id(detail.get("hotelId")));if(detail.get("companyId")!=null)companies.add(id(detail.get("companyId")));if(type.equals("INTERCOMPANY")){hotels.add(id(detail.get("counterpartyHotelId")));companies.add(id(detail.get("counterpartyCompanyId")));}}
  for(UUID h:hotels)access.requireOrgScope(h);if(hotels.isEmpty())throw bad("来源没有明确组织，不能归档");if(type.equals("PAYROLL"))access.requirePermission("finance.payroll");
  String sourceVersion=type+":"+Objects.toString(detail.get("version"),"0")+":"+Objects.toString(detail.get("status"),"")+":"+Objects.toString(detail.getOrDefault("sourceHash",detail.getOrDefault("fileSha256","")),"");if(type.equals("INSIGHT"))sourceVersion+=":"+map(detail.get("snapshot")).get("reportVersion");
  var graph=new ArrayList<Map<String,Object>>();graph.add(node(type,source,"SOURCE",sourceVersion));var events=new ArrayList<Map<String,Object>>();
  if(type.equals("VOUCHER"))events.addAll(jdbc.queryForList("select id,hotel_id,company_id,source_type,source_id,event_key,status,voucher_id,request_hash,metadata from fa_source_event where tenant_id=:tenant and voucher_id=:id order by id",b));
  else if(type.equals("OPERATION"))events.addAll(jdbc.queryForList("select id,hotel_id,company_id,source_type,source_id,event_key,status,voucher_id,request_hash,metadata from fa_source_event where tenant_id=:tenant and metadata->>'documentId'=cast(:id as text) order by id",b));
  else if(Set.of("CLAIM","REVENUE","PAYROLL","INTERCOMPANY","TAX_RETURN").contains(type)){events.addAll(jdbc.queryForList("select id,hotel_id,company_id,source_type,source_id,event_key,status,voucher_id,request_hash,metadata from fa_source_event where tenant_id=:tenant and (source_id=:id or metadata->>'claimId'=cast(:id as text) or metadata->>'businessId'=cast(:id as text) or metadata->>'payrollBatchId'=cast(:id as text) or metadata->>'batchId'=cast(:id as text) or metadata->>'returnId'=cast(:id as text)) and (:tenantScope or hotel_id in (:scopes)) and (:payroll or upper(source_type) not like '%PAYROLL%') order by id",b.addValue("payroll",p.hasPermission("*")||p.hasPermission("finance.payroll"))));}
  if(!cashMovements.isEmpty())events.addAll(jdbc.queryForList("select id,hotel_id,company_id,source_type,source_id,event_key,status,voucher_id,request_hash,metadata from fa_source_event where tenant_id=:tenant and source_id in (:movements) and (:tenantScope or hotel_id in (:scopes)) order by id",base(p).addValue("movements",cashMovements.stream().map(m->m.get("id")).toList())));
  var requiredSources=new ArrayList<Map<String,Object>>();if(type.equals("TAX_RETURN"))taxInputs(detail,graph,requiredSources,hotels,companies);for(var event:events){access.requireOrgScope(id(event.get("hotel_id")));graph.add(node("ACCOUNTING_SOURCE",id(event.get("id")),"REAL_SOURCE_EVENT",event.get("request_hash").toString()));if(event.get("voucher_id")!=null){try{var v=accounting.voucher(id(event.get("voucher_id")));graph.add(node("VOUCHER",id(event.get("voucher_id")),"POSTED_OR_DRAFT_VOUCHER",Objects.toString(v.get("version"))+":"+v.get("status")));requiredSources.add(Map.of("type","VOUCHER","id",event.get("voucher_id")));}catch(cn.sifangguan.hotelaios.shared.security.AccessDeniedException denied){/* Keep the authorized source event but expose no unauthorized voucher details. */}}
   if(type.equals("VOUCHER")){var related=linkedSource(event);if(!related.isEmpty()){String relatedType=related.get("type").toString();UUID relatedId=id(related.get("id"));try{var linked=sourceDetail(relatedType,relatedId);graph.add(node(relatedType,relatedId,"ACTUAL_SOURCE_DOCUMENT",Objects.toString(linked.get("version"),"0")+":"+canonicalHash(clean(linked))));requiredSources.add(related);if(relatedType.equals("TAX_RETURN"))taxInputs(linked,graph,requiredSources,hotels,companies);if(linked.get("attachments")!=null)for(var attachment:rows(linked.get("attachments")))addOriginal(graph,attachment,relatedType,relatedId);if(extended!=null&&FinanceArchiveExtendedSources.TYPES.contains(relatedType)){var actual=extended.resolve(relatedType,relatedId);graph.addAll(rows(actual.get("graph")));requiredSources.addAll(rows(actual.get("requiredSources")));}}catch(cn.sifangguan.hotelaios.shared.security.AccessDeniedException denied){/* Do not copy unauthorized filenames or originals into the graph. */}}}
  }
  if(detail.get("attachments")!=null)for(var attachment:rows(detail.get("attachments"))){var link=node("ORIGINAL",id(attachment.get("id")),"IMMUTABLE_ORIGINAL",Objects.toString(attachment.get("sha256"),""));link.put("sourceType",type);link.put("sourceId",source);link.put("originalName",attachment.get("originalName"));link.put("sha256",attachment.get("sha256"));graph.add(link);}
  if(type.equals("INSIGHT")){for(var report:rows(map(detail.get("snapshot")).get("books"))){var link=node("BOOK_REPORT",id(report.get("bookId")),"EXACT_FROZEN_REPORT_VERSION",Objects.toString(report.get("reportVersion")));link.put("month",map(detail.get("snapshot")).get("month"));graph.add(link);}}
  if(type.equals("TAX_RETURN"))for(var receipt:rows(detail.get("receipts")))graph.add(node("TAX_RECEIPT",id(receipt.get("id")),"EXTERNAL_FILING_OR_PAYMENT_RECEIPT",Objects.toString(receipt.get("externalReference"),"")));
  if(type.equals("MIGRATION")){var link=node("ORIGINAL",source,"IMMUTABLE_SOURCE_EXPORT",Objects.toString(detail.get("fileSha256"),""));link.put("sourceType",type);link.put("sourceId",source);link.put("sha256",detail.get("fileSha256"));link.put("originalName",detail.get("originalName"));graph.add(link);}
  sourceVersion+=":"+canonicalHash(Map.of("payload",clean(detail),"graph",graph,"events",clean(value(events))));graph.getFirst().put("version",sourceVersion);var result=new LinkedHashMap<String,Object>();result.put("sourceType",type);result.put("sourceId",source);result.put("sourceVersion",sourceVersion);result.put("hotelIds",hotels);result.put("companyIds",companies);result.put("payload",clean(detail));result.put("graph",graph);result.put("requiredSources",requiredSources);result.put("events",clean(value(events)));result.put("sensitivePayroll",type.equals("PAYROLL")||events.stream().anyMatch(e->e.get("source_type").toString().toUpperCase(Locale.ROOT).contains("PAYROLL")||map(e.get("metadata")).getOrDefault("sourceType","").toString().toUpperCase(Locale.ROOT).contains("PAYROLL")));result.put("lineageNote","图谱只表示真实已登记关联；冻结报表仅引用同一历史版本，不把当前凭证冒充历史取数。原件下载仍须重新通过原来源权限、范围及完整性校验。");return result;
 }
 public void authorizeLinked(Map<String,Object> snapshot){if(snapshot.get("requiredSources")!=null)for(var source:rows(snapshot.get("requiredSources")))sourceDetail(source.get("type").toString(),id(source.get("id")));}
 /** Only IDs/hashes actually frozen when the return was prepared; never reconstruct an old return from this month's current invoices. */
 private void taxInputs(Map<String,Object> detail,List<Map<String,Object>> graph,List<Map<String,Object>> required,Set<UUID> hotels,Set<UUID> companies){
  var frozen=map(detail.get("snapshot"));if(!"CAPTURED_AT_PREPARATION".equals(frozen.get("inputLineage"))){graph.add(node("SOURCE_LINEAGE_NOT_CAPTURED",id(detail.get("id")),"HISTORICAL_TAX_INPUTS_NOT_RECONSTRUCTED","旧取数版本未捕获逐票链；不以当前票据回填历史"));return;}
  var bases=new HashMap<UUID,Map<String,Object>>();for(var basis:rows(frozen.getOrDefault("inputTaxBases",List.of()))){UUID basisId=id(basis.get("id"));bases.put(basisId,basis);taxScope(basis,hotels,companies);graph.add(node("TAX_INPUT_BASIS",basisId,"FROZEN_INDEPENDENT_TAX_BASIS",Objects.toString(basis.get("sourceHash"),"")+":"+Objects.toString(basis.get("version"),"0")));}
  var indexed=new HashSet<String>();for(var fact:rows(frozen.getOrDefault("inputTaxSources",List.of()))){taxScope(fact,hotels,companies);graph.add(node("INPUT_TAX_FACT",id(fact.get("id")),"FROZEN_TAX_DEDUCTION_OR_TRANSFER",canonicalHash(fact)));UUID basisId=id(fact.get("basisId"));if(basisId==null||!bases.containsKey(basisId))taxOriginal(fact,graph,required,indexed);}
  for(var basis:bases.values()){if("PROCUREMENT_RED".equals(basis.get("sourceKind"))&&basis.get("sourceParentId")!=null)graph.add(node("SUPPLIER_RETURN",id(basis.get("sourceParentId")),"FROZEN_RETURN_FOR_RED_TAX_BASIS",Objects.toString(basis.get("sourceHash"),"")));taxOriginal(basis,graph,required,indexed);}
 }
 private void taxScope(Map<String,Object> fact,Set<UUID> hotels,Set<UUID> companies){UUID hotel=id(fact.get("hotelId")),company=id(fact.get("companyId"));if(hotel==null||company==null)throw conflict("冻结税务逐票链缺少真实组织或法人，不能猜配原件");access.requireOrgScope(hotel);hotels.add(hotel);companies.add(company);}
 private void taxOriginal(Map<String,Object> fact,List<Map<String,Object>> graph,List<Map<String,Object>> required,Set<String> indexed){
  String kind=Objects.toString(fact.get("sourceKind"),"CLAIM");UUID invoice=id(fact.get("invoiceId"));if(invoice==null||!indexed.add(kind+":"+invoice))return;
  var source=map(fact.get("sourceSnapshot"));var actual=source.containsKey("actualSource")?map(source.get("actualSource")):source;String expected=Objects.toString(actual.get("originalSha256"),"");
  if(!expected.matches("[a-f0-9]{64}")){graph.add(node("SOURCE_LINEAGE_NOT_CAPTURED",invoice,"HISTORICAL_ORIGINAL_HASH_NOT_RECONSTRUCTED","本冻结逐票链没有原件哈希，不推定当前原件属于历史取数"));return;}
  try{if(kind.equals("CLAIM")){var matches=jdbc.queryForList("select i.claim_id,i.attachment_id from finance_invoice i join finance_claim c on c.tenant_id=i.tenant_id and c.id=i.claim_id where i.tenant_id=:tenant and i.id=:invoice and c.hotel_id=:hotel and c.company_id=:company",base(access.principal()).addValue("invoice",invoice).addValue("hotel",id(fact.get("hotelId"))).addValue("company",id(fact.get("companyId"))));if(matches.size()!=1)throw conflict("冻结税务报销票未找到同组织同主体的实际原来源");UUID claim=id(matches.getFirst().get("claim_id")),attachment=id(matches.getFirst().get("attachment_id"));claims.detail(claim);var file=output(claims.attachment(claim,attachment));if(!expected.equals(file.get("sha256")))throw conflict("税务冻结链与报销原件哈希不同，不能用当前文件替换");addOriginal(graph,file,"CLAIM",claim);required.add(Map.of("type","CLAIM","id",claim));}
   else if(Set.of("PROCUREMENT","PROCUREMENT_RED").contains(kind)){if(extended==null)throw conflict("采购税务原件专项来源尚未安装");var detail=extended.sourceDetail("INTAKE",invoice);if(!Objects.equals(id(detail.get("hotelId")),id(fact.get("hotelId"))))throw conflict("冻结采购票与真实收票组织不同");var file=claims.intakeOriginal(invoice);if(!expected.equals(file.get("sha256")))throw conflict("税务冻结链与采购收票原件哈希不同，不使用其他票替代");var original=new LinkedHashMap<>(file);original.put("id",invoice);addOriginal(graph,original,"INTAKE",invoice);required.add(Map.of("type","INTAKE","id",invoice));}
   else throw conflict("冻结税务票据来源类型无法核对，不按UUID猜测报销");
  }catch(cn.sifangguan.hotelaios.shared.security.AccessDeniedException denied){graph.add(node("SOURCE_ACCESS_REQUIRED",invoice,"ORIGINAL_PERMISSION_NOT_GRANTED","需实际原报销或收票读取权限；税务/调阅菜单不扩大原件授权"));}
   catch(org.springframework.web.server.ResponseStatusException denied){if(denied.getStatusCode().value()!=403)throw denied;graph.add(node("SOURCE_ACCESS_REQUIRED",invoice,"ORIGINAL_PERMISSION_NOT_GRANTED","需实际原报销或收票读取权限；税务/调阅菜单不扩大原件授权"));}
 }
 private Map<String,Object> sourceDetail(String type,UUID source){if(extended!=null&&(FinanceArchiveExtendedSources.TYPES.contains(type)||Set.of("INTAKE","PROCUREMENT").contains(type)))return extended.sourceDetail(type,source);return switch(type){case "CLAIM"->output(claims.detail(source));case "OPERATION"->operations.detail(source);case "REVENUE"->business.revenueDetail(source);case "PAYROLL"->business.payrollDetail(source);case "INTERCOMPANY"->business.intercompanyDetail(source);case "VOUCHER"->accounting.voucher(source);case "INSIGHT"->insights.detail(source);case "TAX_RETURN"->business.taxReturnDetail(source);case "MIGRATION"->migration.detail(source);default->throw bad("来源无效");};}
 private Map<String,Object> linkedSource(Map<String,Object> event){
  if(extended!=null){var related=extended.fromEvent(event);if(!related.isEmpty())return related;}
  var metadata=map(event.get("metadata"));if(metadata.get("claimId")!=null)return Map.of("type","CLAIM","id",id(metadata.get("claimId")));if(metadata.get("documentId")!=null)return Map.of("type","OPERATION","id",id(metadata.get("documentId")));String table=Objects.toString(metadata.get("businessTable"),"");UUID business=id(metadata.get("businessId"));if(business==null)return Map.of();if(table.equals("fb_revenue_entry")){var found=jdbc.queryForList("select batch_id from fb_revenue_entry where tenant_id=:tenant and id=:id",base(access.principal()).addValue("id",business));return found.isEmpty()?Map.of():Map.of("type","REVENUE","id",found.getFirst().get("batch_id"));}String type=switch(table){case "fb_payroll_batch"->"PAYROLL";case "fb_intercompany"->"INTERCOMPANY";case "fb_tax_return"->"TAX_RETURN";default->"";};return type.isEmpty()?Map.of():Map.of("type",type,"id",business);
 }
 private void addOriginal(List<Map<String,Object>> graph,Map<String,Object> attachment,String type,UUID source){var link=node("ORIGINAL",id(attachment.get("id")),"IMMUTABLE_ORIGINAL",Objects.toString(attachment.get("sha256"),""));link.put("sourceType",type);link.put("sourceId",source);link.put("originalName",attachment.get("originalName"));link.put("sha256",attachment.get("sha256"));graph.add(link);}
 private static Map<String,Object> node(String type,UUID id,String relation,String version){var node=new LinkedHashMap<String,Object>();node.put("type",type);node.put("id",id);node.put("relation",relation);node.put("version",version);return node;}
 static String canonicalHash(Object value){try{return FinanceService.hash(JSON.writer().with(com.fasterxml.jackson.databind.SerializationFeature.ORDER_MAP_ENTRIES_BY_KEYS).writeValueAsString(value));}catch(Exception e){throw new IllegalStateException("档案规范化失败",e);}}
 private static Object clean(Object value){if(value instanceof Map<?,?> map){var out=new LinkedHashMap<String,Object>();for(var e:map.entrySet()){String key=e.getKey().toString();if(!Set.of("objectKey","object_key","fileBytes","file_bytes","canEdit","canReview","canPay","canSettle","canSubmit").contains(key))out.put(key,clean(e.getValue()));}return out;}if(value instanceof Collection<?> list)return list.stream().map(FinanceArchiveSources::clean).toList();return value;}
}
